import{_ as o,l as r,o as a,c as d,v as t,p as n,x as s,d as l,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"systemd 单元与依赖","description":"","frontmatter":{"title":"systemd 单元与依赖","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/systemd-units.md","filePath":"cs/systemd-units.md","lastUpdated":1789023840000}'),p={name:"cs/systemd-units.md"};function h(u,e,f,_,E,y){const i=r("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="systemd-单元与依赖" tabindex="-1">systemd 单元与依赖 <a class="header-anchor" href="#systemd-单元与依赖" aria-label="Permalink to &quot;systemd 单元与依赖&quot;">​</a></h1><div class="epigraph"><p>systemd 用单元描述服务、挂载、socket：依赖图决定启动顺序，socket 激活让守护在第一连接才起。</p><footer>—— 据 systemd 文档对 unit 的说明；Poettering 对依赖与并行启动的论述</footer></div><p><a href="/cs/initramfs-pivot">initramfs</a> 把 PID 1 交给真根上的 init。缺口是 <strong>systemd 单元模型</strong>：不是 SysV 脚本百科，也不把桌面 session 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>After=</code>/<code>Requires=</code>/<code>Wants=</code> 语义不同：硬依赖失败则自己失败。socket 单元：先听端口。缺口：cgroup 与单元默认绑 <a href="/cs/memcg">memcg</a>/cpu；与 <a href="/cs/linux-capabilities">capabilities</a> 的 <code>AmbientCapabilities</code>。本课不把每个指令写成手册。</p><p><span class="marginnote">事务：一次启动计算最小图。循环依赖会打破或警告。对象是 PID 1 策略，不是内核调度器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解析 unit → 建图 → 并行启动无依赖者 → 监督重启。对照 <a href="/cs/timer-wheel">timer wheel</a>：<code>timer</code> 单元用日历或单调时间。对照 <a href="/cs/tx-path-qdisc">qdisc</a>：无关。对照 LSM：<code>PrivateTmp</code> 等用命名空间落地。</p>',8)),(a(),n(m,null,{default:s(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22unit%20%E6%96%87%E4%BB%B6%22%5D%20--%3E%20G%5B%22%E4%BE%9D%E8%B5%96%E5%9B%BE%22%5D%0A%20%20G%20--%3E%20PAR%5B%22%E5%B9%B6%E8%A1%8C%E5%90%AF%E5%8A%A8%22%5D%0A%20%20SOCK%5B%22socket%20%E5%8D%95%E5%85%83%22%5D%20--%3E%20ACT%5B%22%E9%A6%96%E8%BF%9E%E5%86%8D%20exec%20%E6%9C%8D%E5%8A%A1%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>单元把「开机要做的事」收成可依赖的对象，使并行与重启策略可声明。它不替代内核。不要写成 init 战争。与 <a href="/cs/kernel-audit">audit</a>：服务可带自己的日志，journal 是用户态。</p><p>错误的 <code>Type=forking</code> 会让依赖提前满足。</p><p>实现上：Requires 失败会把依赖者拉倒，Wants 不会。Type=notify 等 sd_notify 才算启动完成。socket 激活让崩溃的守护在下一连接再起。 读法上只引用<a href="/cs/initramfs-pivot">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>systemd 单元与依赖</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入用户 manager 的全部。不保证嵌入式 busybox init。下一课内核如何被 PID 1 之前参数化：命令行。</p><p>版本字段会变，课序钉的是机制对象「systemd 单元与依赖」，不是某一主线内核的结构体名。 后课默认：用户态服务是带依赖的单元。内核 cmdline，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>systemd 单元构成依赖图并可 socket 激活。</li><li>与 cgroup/命名空间接口相连。</li><li>内核命令行是下一课。</li><li>出处：systemd.unit(5)；systemd 文档。</li></ul>',11))])}const b=o(p,[["render",h]]);export{T as __pageData,b as default};
